type Again<T> = { [K in keyof T]: T[K] };
type Maybe<T> = { [K in keyof T]?: T[K] };
type Input = { a: string; b: number };
declare const mapped: Again<Input>, maybe: Maybe<Input>;
const s: string = mapped.a;
const n: number = mapped.b;
const wrong: number = mapped.a;
const optional: string = maybe.a;
